INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (2, 1, 2, "vo_minigame_1013_icon_2_002_001", 1000, 2, "訓練はまだ\nここからですわ", "vo_minigame_1013_icon_1_002_001", 3000, "調子が上がって\nきたなっ");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (2, 2, 2, "vo_minigame_1013_icon_2_003_001", 5000, 2, "クスクス、悪くない\n流れですわね", "vo_minigame_1013_icon_1_003_001", 3000, "ほらほら、\nまだいけるだろ？");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (2, 3, 3, "vo_minigame_1013_icon_2_004_001", 10000, 2, "すばらしい\n記録ですわ", "vo_minigame_1013_icon_1_004_001", 3000, "へへっ、おまえら\nやるじゃねえか！");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (3, 4, 3, "vo_minigame_1013_icon_2_005_001", 10000, 2, "乗りに乗って\nいますわね", "vo_minigame_1013_icon_1_005_001", 3000, "あたしたちはまだ\n止まらねえぜ！");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (3, 5, 3, "vo_minigame_1013_icon_2_005_002", 10000, 2, "まだまだ行きます\nついてきなさい", "vo_minigame_1013_icon_1_005_002", 3000, "見てろよ！\nマコト班の快進撃だ！");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (3, 6, 3, "vo_minigame_1013_icon_2_005_003", 10000, 2, "エリコ班の\n本領発揮ですわ！", "vo_minigame_1013_icon_1_005_003", 3000, "うおぉぉっ！\n絶好調だぜ！");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (4, 7, 3, "vo_minigame_1013_icon_2_006_001", 0, 2, "ここからは\n前人未到の領域です！", "vo_minigame_1013_icon_1_006_001", 3000, "どこまで行けるか\n楽しみだなっ！");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (5, 8, 4, "vo_minigame_1013_icon_2_007_001", 1, 3, "厄介でしたわ…", "vo_minigame_1013_icon_1_007_001", 1000, "まだ諦めんなよっ");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (5, 9, 4, "vo_minigame_1013_icon_2_007_002", 1, 3, "油断大敵です", "vo_minigame_1013_icon_1_007_002", 1000, "冷やっとしたぜ…！");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (5, 10, 4, "vo_minigame_1013_icon_2_007_003", 1, 3, "忌々しいっ…", "vo_minigame_1013_icon_1_007_003", 1000, "弱音を吐くなっ");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (6, 11, 3, "vo_minigame_1013_icon_2_008_001", 99, 4, "大所帯ですわね", "vo_minigame_1013_icon_1_008_001", 1500, "マコト班集合！");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (6, 12, 3, "vo_minigame_1013_icon_2_008_002", 99, 4, "エリコ班へようこそ", "vo_minigame_1013_icon_1_008_002", 1500, "連携してくぞ！");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (8, 13, 6, "vo_minigame_1013_icon_2_020_001", 0, 1, "ナナカちゃんに\nお任せあれ", "vo_minigame_1013_icon_1_020_001", 3000, "みんなに力を！");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (9, 14, 7, "vo_minigame_1013_icon_2_022_001", 0, 1, "はっはっは！\n任せろ！", "vo_minigame_1013_icon_1_022_001", 3000, "任せてくれたまえ");
INSERT INTO `v1_441d5356c1bc9986b1eef84abb7f12d05223a1f4682112e3dfff9fbff6cb1d86` VALUES (10, 15, 8, "vo_minigame_1013_icon_2_023_001", 0, 1, "どんどんいくわよ", "vo_minigame_1013_icon_1_023_001", 3000, "ほな、いきまひょか");
